// Zuordnung der Scans in `scan/` zu ihrer Adresse in der Mediathek von
// adhs.expert. Generiert, nicht von Hand gepflegt.
//
// Die Dateien wurden am 12. November 2026 ueber die REST-API hochgeladen
// (`POST /wp-json/wp/v2/media`). Der Name in der Mediathek ist der Scanname in
// ASCII (Umlaute aufgeloest, Klammern und Kommas zu `_`); wo WordPress einen
// Namen schon belegt fand, haengte es `-1` an. Darum ist die Adresse **nicht**
// aus dem Dateinamen berechenbar und muss hier stehen.
//
// Lizenz: GPL-3.0

/// Adresse des Scans auf adhs.expert, oder `None` wenn er nicht hochgeladen ist.
pub fn url(datei: &str) -> Option<&'static str> {
    MEDIEN
        .iter()
        .find(|(d, _)| *d == datei)
        .map(|(_, u)| *u)
}

